function draw(ctx, t, p) {
  var W = 960, H = 540;
  var z = Number(t); if (!isFinite(z)) z = 0;
  z = Math.max(0, Math.min(1, z));
  var mag = Number(p.h); if (!isFinite(mag)) mag = 0.5;
  mag = Math.max(0.01, Math.min(1, mag));
  var preset = Number(p.preset) >= 0.5 ? 1 : 0;
  var mode = Math.max(0, Math.min(2, Math.round(Number(p.display) || 0)));
  var sec = z * 34;
  var scene = sec < 10 ? 1 : (sec < 22 ? 2 : 3);
  var local = scene === 1 ? sec / 10 : scene === 2 ? (sec - 10) / 12 : (sec - 22) / 12;
  var isX2 = preset === 0;
  var a = 1;
  function f(x) { return isX2 ? x * x : 2 * x + 1; }
  function df() { return isX2 ? 2 : 2; }
  var h;
  if (scene === 1) {
    h = mag * (1 - 0.55 * Math.min(1, local));
  } else if (scene === 2) {
    var q = local < 0.5 ? local * 2 : (local - 0.5) * 2;
    var side = local < 0.5 ? 1 : -1;
    h = side * mag * (1 - 0.9 * q);
  } else {
    var seq = [1, 0.5, 0.1, 0.01];
    var k = Math.min(3, Math.floor(local * 4));
    h = seq[k] * Math.max(0.1, Math.min(2, mag / 0.5));
    h = Math.min(1, h);
  }
  if (Math.abs(h) < 0.01) h = h < 0 ? -0.01 : 0.01;
  var ya = f(a), xb = a + h, yb = f(xb), dy = yb - ya;
  var slope = dy / h, tangent = df();
  var left = 70, bottom = 400, pw = 585, ph = 285;
  var xmin = -2, xmax = 4, ymin = -1, ymax = 10;
  function X(x) { return left + (x - xmin) / (xmax - xmin) * pw; }
  function Y(y) { return bottom - (y - ymin) / (ymax - ymin) * ph; }
  function txt(s, x, y, n, c, al) {
    ctx.font = (n || 17) + 'px sans-serif';
    ctx.fillStyle = c || '#263238'; ctx.textAlign = al || 'left'; ctx.textBaseline = 'middle';
    ctx.fillText(String(s), x, y);
  }
  function ln(x1, y1, x2, y2, c, w, dash) {
    ctx.save(); ctx.strokeStyle = c; ctx.lineWidth = w || 2; ctx.setLineDash(dash || []);
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); ctx.restore();
  }
  ctx.fillStyle = '#f8fbff'; ctx.fillRect(0, 0, W, H);
  txt('从割线到切线：导数是瞬时变化率', 480, 28, 24, '#17324d', 'center');
  txt('第' + scene + '幕：' + (scene === 1 ? '两点确定割线' : scene === 2 ? '双侧逼近切线' : 'x² 的具体计算'), 48, 64, 19, '#6b3fa0');
  ctx.strokeStyle = '#d4e1ec'; ctx.lineWidth = 1; ctx.strokeRect(35, 85, 890, 350);
  for (var gx = -2; gx <= 4; gx++) ln(X(gx), Y(ymin), X(gx), Y(ymax), '#e5edf3', 1);
  for (var gy = 0; gy <= 10; gy += 2) ln(X(xmin), Y(gy), X(xmax), Y(gy), '#e5edf3', 1);
  ln(X(xmin), Y(0), X(xmax), Y(0), '#334e68', 2);
  ln(X(0), Y(ymin), X(0), Y(ymax), '#334e68', 2);
  for (gx = -2; gx <= 4; gx++) txt(gx, X(gx), Y(0) + 17, 14, '#526b7a', 'center');
  for (gy = 0; gy <= 10; gy += 2) txt(gy, X(0) - 10, Y(gy), 14, '#526b7a', 'right');
  txt('x', X(xmax) + 12, Y(0), 17, '#263238'); txt('y', X(0), Y(ymax) - 12, 17, '#263238');
  ctx.save(); ctx.strokeStyle = '#2878c8'; ctx.lineWidth = 3; ctx.beginPath();
  var started = false;
  for (var i = 0; i <= 220; i++) {
    var xx = xmin + (xmax - xmin) * i / 220, yy = f(xx);
    if (yy >= ymin && yy <= ymax) { if (!started) { ctx.moveTo(X(xx), Y(yy)); started = true; } else ctx.lineTo(X(xx), Y(yy)); }
  }
  ctx.stroke(); ctx.restore();
  var Ax = X(a), Ay = Y(ya), Bx = X(xb), By = Y(yb);
  var tlo = xmin, thi = xmax;
  var ty1 = ya + tangent * (tlo - a), ty2 = ya + tangent * (thi - a);
  ctx.save(); ctx.beginPath(); ctx.rect(left, 100, pw, 300); ctx.clip();
  ln(X(tlo), Y(ty1), X(thi), Y(ty2), '#8d4bbb', 2.5, [7, 5]);
  ctx.restore();
  ln(Ax, Ay, Bx, By, '#ee8b2d', 4);
  ln(Ax, Ay, Bx, Ay, '#ee8b2d', 2, [5, 4]);
  ln(Bx, Ay, Bx, By, '#ee8b2d', 2, [5, 4]);
  ctx.fillStyle = '#17324d'; ctx.beginPath(); ctx.arc(Ax, Ay, 6, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ee8b2d'; ctx.beginPath(); ctx.arc(Bx, By, 6, 0, Math.PI * 2); ctx.fill();
  txt('A=(1,' + ya.toFixed(2) + ')', Ax + 10, Ay - 17, 17, '#17324d');
  txt('B=(1+h,' + yb.toFixed(2) + ')', Bx + 10, By - 17, 17, '#b55b12');
  txt('h=' + h.toFixed(2), (Ax + Bx) / 2, Ay + 21, 17, '#b55b12', 'center');
  txt('Δy=' + dy.toFixed(2), Bx + 40, (Ay + By) / 2, 17, '#b55b12', 'center');
  ctx.fillStyle = '#ffffff'; ctx.fillRect(682, 100, 225, 302); ctx.strokeStyle = '#c4d6e5'; ctx.strokeRect(682, 100, 225, 302);
  txt('数值与公式', 795, 122, 20, '#17324d', 'center');
  if (mode === 0) {
    txt('差商 m=Δy/h', 700, 158, 18, '#b55b12');
    txt('m=' + slope.toFixed(4), 700, 190, 19, '#b55b12');
    txt('h=' + h.toFixed(2) + '（h≠0）', 700, 222, 18, '#263238');
    txt('Δy=' + dy.toFixed(2), 700, 254, 18, '#263238');
    txt(scene === 2 ? (h > 0 ? '右侧 h>0' : '左侧 h<0') : '有限差商', 700, 294, 18, '#2878c8');
    txt('有限逼近不等于极限', 700, 330, 16, '#6b3fa0');
  } else if (mode === 1) {
    if (isX2) {
      txt('[f(1+h)-f(1)]/h', 700, 158, 17, '#263238');
      txt('=[(1+h)²−1]/h', 700, 190, 17, '#263238');
      txt('=[2h+h²]/h', 700, 222, 18, '#263238');
      txt('=2+h（h≠0）', 700, 254, 18, '#b55b12');
      txt('h→0 时趋向 2', 700, 294, 18, '#6b3fa0');
    } else {
      txt('[2(1+h)+1−3]/h', 700, 158, 17, '#263238');
      txt('=2h/h=2', 700, 196, 18, '#b55b12');
      txt('两侧差商都为 2', 700, 238, 18, '#6b3fa0');
      txt('约去 h 需 h≠0', 700, 280, 17, '#263238');
    }
  } else {
    txt('切线斜率 f′(1)=' + tangent.toFixed(2), 700, 164, 18, '#6b3fa0');
    txt(isX2 ? 'y−1=2(x−1)' : 'y−3=2(x−1)', 700, 204, 20, '#2878c8');
    txt('h=0 仅为极限位置', 700, 250, 17, '#b55b12');
    txt('双侧极限相同 ⇒ 可导', 700, 292, 17, '#6b3fa0');
    txt('切线与曲线在 A 附近重合', 700, 332, 16, '#263238');
  }
  txt('预设 ' + (isX2 ? '① f(x)=x²，a=1' : '② f(x)=2x+1，a=1') + '   |   ' + sec.toFixed(1) + ' / 34 秒', 480, 458, 17, '#263238', 'center');
  var finiteSlope = isFinite(slope) ? slope : 0;
  return {metrics:{scene:scene,h:h,delta_y:dy,secant_slope:finiteSlope,derivative:tangent,function:isX2?'x^2':'2x+1',seconds:sec}};
}
